/******** Structured error handling with logging for silent failure operations */
// NOTE: serverLogger is imported but only accessed inside function bodies (never at
// module-eval time). This is safe even with circular deps because by the time any
// function in this module is called, all modules have finished initializing.
import { serverLogger } from "../utils/logger/logger.js";
import { redactForSerialization } from "../utils/logger/redact.js";
import { ERROR_DIAGNOSTIC_MAX_LENGTH_CHARS, isAbsoluteFilesystemPathForDiagnostic, sanitizeDiagnosticText, sanitizeStackDiagnosticText, snapshotErrorForBoundary, snapshotThrowableDiagnosticRedactingPath, } from "./safe-diagnostics.js";
const arrayIsArray = Array.isArray;
const ABSOLUTE_PATH_REDACTION = "<absolute-path>";
function sanitizeFilesystemContextPath(path) {
    if (path.length > ERROR_DIAGNOSTIC_MAX_LENGTH_CHARS)
        return ABSOLUTE_PATH_REDACTION;
    const sanitized = sanitizeDiagnosticText(path);
    return isAbsoluteFilesystemPathForDiagnostic(sanitized) ? ABSOLUTE_PATH_REDACTION : sanitized;
}
function snapshotDiagnostic(error, filesystemPath) {
    if (filesystemPath !== undefined &&
        filesystemPath.length > ERROR_DIAGNOSTIC_MAX_LENGTH_CHARS) {
        return {
            message: snapshotThrowableDiagnosticRedactingPath(error, filesystemPath, ABSOLUTE_PATH_REDACTION),
        };
    }
    const snapshot = snapshotErrorForBoundary(error);
    const message = filesystemPath !== undefined
        ? snapshotThrowableDiagnosticRedactingPath(error, filesystemPath, ABSOLUTE_PATH_REDACTION)
        : snapshot.slug === "unknown-error"
            ? snapshot.detail ?? snapshot.message
            : snapshot.message;
    return {
        message,
        stack: snapshot.stack,
    };
}
function snapshotContext(context) {
    try {
        return {
            operation: sanitizeDiagnosticText(context.operation),
            path: context.path === undefined ? undefined : sanitizeDiagnosticText(context.path),
            slug: context.slug === undefined ? undefined : sanitizeDiagnosticText(context.slug),
            details: context.details,
        };
    }
    catch {
        return { operation: "unknown-operation" };
    }
}
function sanitizedDetails(details) {
    if (!details)
        return {};
    const snapshot = redactForSerialization(details);
    return snapshot && typeof snapshot === "object" && !arrayIsArray(snapshot)
        ? snapshot
        : {};
}
function logErrorBestEffort(error, context, logLevel = "debug", includeStack = false, filesystemPath) {
    try {
        const safeContext = snapshotContext(filesystemPath === undefined
            ? context
            : { ...context, path: sanitizeFilesystemContextPath(filesystemPath) });
        const diagnostic = snapshotDiagnostic(error, filesystemPath);
        const message = sanitizeDiagnosticText(diagnostic.message);
        const logData = {
            ...sanitizedDetails(safeContext.details),
            path: safeContext.path,
            slug: safeContext.slug,
            errorMessage: message,
        };
        if (includeStack && diagnostic.stack) {
            logData.stack = sanitizeStackDiagnosticText(diagnostic.stack);
        }
        const logMessage = `[${safeContext.operation}] Silent failure: ${message}`;
        switch (logLevel) {
            case "error":
                serverLogger.error(logMessage, logData);
                return;
            case "warn":
                serverLogger.warn(logMessage, logData);
                return;
            default:
                serverLogger.debug(logMessage, logData);
        }
    }
    catch {
        // Logging is diagnostic only and must never replace the configured fallback.
    }
}
async function withFilesystemErrorContext(operation, path, operationName, fallback) {
    try {
        return await operation();
    }
    catch (error) {
        logErrorBestEffort(error, { operation: operationName, path }, "debug", false, path);
        return fallback;
    }
}
/** Execute async operation with error logging and fallback */
export async function withErrorContext(operation, context, options) {
    try {
        return await operation();
    }
    catch (error) {
        logErrorBestEffort(error, context, options.logLevel, options.includeStack);
        return options.fallback;
    }
}
/** Execute sync operation with error logging and fallback */
export function withErrorContextSync(operation, context, options) {
    try {
        return operation();
    }
    catch (error) {
        logErrorBestEffort(error, context, options.logLevel, options.includeStack);
        return options.fallback;
    }
}
/** Safe file stat with logging */
export function safeFileStat(adapter, path, operation) {
    return withFilesystemErrorContext(() => adapter.fs.stat(path), path, operation, null);
}
/** Safe file read with logging */
export function safeFileRead(adapter, path, operation) {
    return withFilesystemErrorContext(() => adapter.fs.readFile(path), path, operation, null);
}
/** Safe directory read with logging */
export async function safeReadDir(adapter, path, operation) {
    try {
        const results = [];
        for await (const entry of adapter.fs.readDir(path))
            results.push(entry);
        return results;
    }
    catch (error) {
        logErrorBestEffort(error, { operation, path }, "debug", false, path);
        return [];
    }
}
/** Create a scoped error context helper for multiple related operations */
export function createErrorScope(operationPrefix) {
    function buildContext(details) {
        try {
            return {
                operation: operationPrefix,
                path: details.path,
                slug: details.slug,
                details: details.details,
            };
        }
        catch {
            return { operation: operationPrefix };
        }
    }
    return {
        run(operation, details, fallback, logLevel = "debug") {
            return withErrorContext(operation, buildContext(details), { fallback, logLevel });
        },
        runSync(operation, details, fallback, logLevel = "debug") {
            return withErrorContextSync(operation, buildContext(details), { fallback, logLevel });
        },
    };
}
